import { yupResolver } from "@hookform/resolvers/yup";
import { LoadingButton } from "@mui/lab";
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  FormLabel,
  Grid,
  IconButton,
  Radio,
  RadioGroup,
  TextField,
} from "@mui/material";
import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import UploadIcon from "@mui/icons-material/Upload";
import "react-datepicker/dist/react-datepicker.css";

const validationSchema = yup.object().shape({
  title: yup
    .string()
    .trim()
    .required("Please enter IT Solution Features.")
    .max(50, "Title must be at most 50 characters."),
});

const FileInput = ({ inputId, accept, onChange, selectedFileName, error }) => (
  <>
    <Button
      startIcon={<UploadIcon />}
      variant="contained"
      sx={{ bgcolor: "#fff", border: "1px solid #6B6B6B", color: "#000" }}
      onClick={() => document.getElementById(inputId).click()}
    >
      Choose File
    </Button>
    <input
      id={inputId}
      name={inputId}
      type="file"
      accept={accept}
      onChange={onChange}
      style={{ display: "none" }}
    />
    <FormHelperText
      variant="body2"
      sx={{ color: "#6B6B6B", marginBottom: "8px" }}
    >
      {selectedFileName || "No file chosen"}
    </FormHelperText>
    <FormHelperText
      variant="body2"
      sx={{ color: "#6B6B6B", marginBottom: "8px" }}
    >
      {error && error.message}
    </FormHelperText>
  </>
);

const DialogFeatures = (props) => {
  const { mode, open, toggle, dataToEdit, onSuccess, itSolutionId } = props;

  const [loading, setLoading] = useState(false);
  const [dialogTitle, setDialogTitle] = useState("");

  const {
    control,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm({
    defaultValues: {
      title: "",
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });

  const [selectedFileNames, setSelectedFileNames] = useState({
    iconImage: "",
  });

  const [iconImage, setIconImage] = useState(null);

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      setIconImage(selectedFile);
      setSelectedFileNames({
        ...selectedFileNames,
        iconImage: selectedFile.name,
      });
    }
  };
  console.log(iconImage);

  useEffect(() => {
    if (open) {
      setLoading(false);
      setDialogTitle(mode === "add" ? "Add" : "Edit");
      if (mode === "edit" && dataToEdit) {
        setSelectedFileNames({
          iconImage: dataToEdit?.iconImage || "",
        });
        setIconImage(null);
      } else {
        setSelectedFileNames({ iconImage: "" });
        setIconImage(null);
      }

      reset({
        title: dataToEdit?.title || "",
      });
    }
  }, [dataToEdit, mode, open, reset]);

  const onSubmit = (data) => {
    const payload = new FormData();
    payload.append("title", data.title);
    payload.append("sub_it_solution_list_id", itSolutionId);
    if (iconImage) {
      payload.append("icon_image", iconImage);
    }

    setLoading(true);

    let apiInstance = null;

    if (mode === "edit") {
      apiInstance = axiosInstance.patch(
        ApiEndPoints.ITSolutionFeatures.edit(dataToEdit.id),
        payload,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );
    } else {
      apiInstance = axiosInstance.post(
        ApiEndPoints.ITSolutionFeatures.create,
        payload,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );
    }

    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  return (
    <>
      <Dialog
        open={open}
        onClose={toggle}
        fullWidth
        maxWidth="sm"
        scroll="paper"
      >
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box>{dialogTitle}</Box>
          <IconButton
            aria-label="close"
            onClick={toggle}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent
          sx={{ pb: 8, px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}
        >
          <form id="features-form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={4}>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="title"
                    error={Boolean(errors.title)}
                  >
                    Title
                  </FormLabel>
                  <Controller
                    name="title"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Title"
                        autoFocus
                        onChange={onChange}
                        id="title"
                        value={value}
                        error={Boolean(errors.title)}
                      />
                    )}
                  />
                  {errors.title && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.title.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth>
                  <FormLabel required htmlFor="icon_image">
                    Icon Image
                  </FormLabel>
                  <FileInput
                    inputId="icon_image"
                    accept=".jpg, .jpeg, .png, .pdf"
                    onChange={(e) => handleFileChange(e)}
                    selectedFileName={selectedFileNames.iconImage}
                    error={errors.icon_image}
                  />
                </FormControl>
              </Grid>
            </Grid>
          </form>
        </DialogContent>
        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="features-form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DialogFeatures;
